return [{json: {request: {model: c.model, messages: [{role: 'system', content: INSTRUCTION}, {role: 'user', content: JSON.stringify({invoice_text: text})}], max_tokens: 800, temperature: 0, stream: false, response_format: {type: 'json_object'}, provider: {sort: 'success_rate'}}}}];

const response = $input.first().json;
if (!Number.isInteger(response.statusCode) || response.statusCode < 200 || response.statusCode >= 300) throw new Error('API request failed. Check the HTTP status, credential, model access, and account quota. No automatic retry.');
const body = typeof response.body === 'string' ? JSON.parse(response.body) : response.body;
const choice = body?.choices?.[0];
if (!choice || choice.finish_reason !== 'stop' || typeof choice.message?.content !== 'string' || choice.message.refusal || (Array.isArray(choice.message.tool_calls) ? choice.message.tool_calls.length > 0 : !!choice.message.tool_calls)) throw new Error('Expected a complete text answer. Review the response before rerunning. Diagnostics: ' + JSON.stringify({finish_reason: choice?.finish_reason ?? null, content_type: typeof choice?.message?.content, choices: body?.choices?.length ?? 0, body_keys: Object.keys(body ?? {})}));
const result = JSON.parse(choice.message.content);
if (!result || typeof result !== 'object' || Array.isArray(result)) throw new Error('Expected a JSON object.');
