const cents = x => { if (typeof x !== 'string' || !/^(0|[1-9][0-9]{0,7})\.[0-9]{2}$/.test(x)) throw new Error('Invalid money string.'); return Number(x.replace('.', '')); };
const total = cents(result.grand_total);
