  if (!i || typeof i.sku !== 'string' || !/^[A-Za-z0-9_-]{1,60}$/.test(i.sku) || seen.has(i.sku) || !Number.isInteger(i.quantity) || i.quantity < 1 || i.quantity > 10000) throw new Error('Invalid or duplicate invoice item.');
